以下是一個 debounce 函式的實作，以及使用範例。

```javascript
/**
 * 建立一個 debounce 包裝函式。
 * 在最後一次呼叫後等待 `wait` 毫秒才會真正執行 `fn`。
 *
 * @param {Function} fn - 要被防抖動的函式
 * @param {number} wait - 等待時間（毫秒），預設 300
 * @param {boolean} [immediate=false] - 若為 true，則在第一次呼叫時立即執行，之後的呼叫需等待 wait 毫秒後才會再次生效
 * @returns {Function} 防抖動後的函式，並附有 cancel() 方法
 */
function debounce(fn, wait = 300, immediate = false) {
  let timeoutId = null;

  function debounced(...args) {
    const context = this;
    const callNow = immediate && timeoutId === null;

    clearTimeout(timeoutId);

    timeoutId = setTimeout(() => {
      timeoutId = null;
      if (!immediate) {
        fn.apply(context, args);
      }
    }, wait);

    if (callNow) {
      fn.apply(context, args);
    }
  }

  // 取消尚未執行的呼叫
  debounced.cancel = function () {
    clearTimeout(timeoutId);
    timeoutId = null;
  };

  return debounced;
}
```

## 使用範例

```javascript
// 範例 1：搜尋輸入框，使用者停止打字 500 毫秒後才送出搜尋
const searchInput = document.querySelector('#search');

const handleSearch = debounce((event) => {
  console.log('搜尋關鍵字：', event.target.value);
  // 實際情況可在此呼叫 API
}, 500);

searchInput.addEventListener('input', handleSearch);

// 範例 2：立即執行模式，第一次觸發時馬上執行
const handleClick = debounce(() => {
  console.log('按鈕被點擊');
}, 1000, true);

// 範例 3：取消尚未執行的防抖動呼叫
const save = debounce(() => {
  console.log('自動儲存');
}, 2000);

save();
save.cancel(); // 取消，不會執行 console.log
```

## 說明

- **基本模式**（預設）：連續觸發時，只有在最後一次呼叫後經過 `wait` 毫秒才執行。
- **立即模式**（`immediate = true`）：第一次呼叫立即執行，之後在 `wait` 毫秒內的呼叫會被忽略。
- **`cancel()`**：可取消等待中的執行，適合在元件卸載或頁面切換時清除計時器。
- 使用 `this` 與 `...args` 保留原始函式的上下文與參數。

```javascript
/**
 * 建立一個 debounce 函式：在最後一次呼叫後等待 `wait` 毫秒才執行。
 * @param {Function} fn 要被防抖的函式
 * @param {number} wait 等待時間（毫秒）
 * @param {{ leading?: boolean }} [options] leading 為 true 時，第一次呼叫立即執行
 * @returns {Function & { cancel: () => void }}
 */
function debounce(fn, wait = 300, { leading = false } = {}) {
  let timer = null;

  function debounced(...args) {
    const callNow = leading && timer === null;

    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!leading) fn.apply(this, args);
    }, wait);

    if (callNow) fn.apply(this, args);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

// 使用範例
const onSearch = debounce((keyword) => {
  console.log("搜尋：", keyword);
}, 500);

onSearch("a");
onSearch("ab");
onSearch("abc"); // 只有最後一次會在 500ms 後印出「搜尋： abc」

// 立即執行版本（第一次呼叫馬上執行，之後停止輸入 500ms 內的呼叫被忽略）
const onSave = debounce(() => console.log("已儲存"), 500, { leading: true });

onSave(); // 立即印出「已儲存」
onSave(); // 被防抖，不會立即執行

// 取消待執行的呼叫
onSearch.cancel();
```

