## Debounce 函式

```javascript
/**
 * 建立一個 debounce 包裝函式。
 * 連續呼叫時，只有在最後一次呼叫後等待 `delay` 毫秒，才會真正執行 `fn`。
 *
 * @param {Function} fn - 要被延遲執行的函式
 * @param {number} delay - 等待時間（毫秒）
 * @param {boolean} [immediate=false] - 若為 true，則在第一次呼叫時立即執行，之後的呼叫在停止 delay 毫秒後才會再次生效
 * @returns {Function} debounce 後的函式，附帶 cancel() 方法
 */
function debounce(fn, delay, immediate = false) {
  let timer = null;

  function debounced(...args) {
    const context = this;
    const callNow = immediate && !timer;

    clearTimeout(timer);

    timer = setTimeout(() => {
      timer = null;
      if (!immediate) {
        fn.apply(context, args);
      }
    }, delay);

    if (callNow) {
      fn.apply(context, args);
    }
  }

  // 取消尚未執行的呼叫
  debounced.cancel = function () {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}
```

## 使用範例

```javascript
// 模擬搜尋輸入框的情境
function search(keyword) {
  console.log(`搜尋：${keyword}`);
}

const debouncedSearch = debounce(search, 500);

// 快速連續呼叫，只會在最後一次呼叫後 500ms 執行一次
debouncedSearch('a');
debouncedSearch('ap');
debouncedSearch('app');
debouncedSearch('appl');
debouncedSearch('apple');
// 輸出（約 500ms 後）：搜尋：apple

// 立即執行版本：第一次呼叫馬上執行，之後的連續呼叫會被忽略直到停止 500ms
const debouncedSave = debounce(() => console.log('已儲存'), 500, true);

debouncedSave(); // 立即輸出：已儲存
debouncedSave(); // 被忽略
debouncedSave(); // 被忽略

// 取消尚未執行的呼叫
debouncedSearch('banana');
debouncedSearch.cancel(); // 不會有任何輸出
```

## 說明

- **基本用法**：每次呼叫都會重設計時器，只有在停止呼叫 `delay` 毫秒後才會執行一次。
- **`immediate` 參數**：設為 `true` 時改為「前緣觸發」，第一次呼叫立即執行。
- **`this` 與參數保留**：透過 `fn.apply(context, args)` 保留原本的 `this` 與傳入的參數。
- **`cancel()`**：可手動取消尚未執行的延遲呼叫，適合在元件卸載時清除計時器。

```javascript
/**
 * 建立一個 debounce 函式：在最後一次呼叫後等待 `wait` 毫秒才執行。
 * @param {Function} fn - 要被防抖的函式
 * @param {number} wait - 等待時間（毫秒）
 * @param {boolean} [immediate=false] - 若為 true，則在第一次呼叫時立即執行
 * @returns {Function} 防抖後的函式，並附有 cancel() 方法
 */
function debounce(fn, wait = 300, immediate = false) {
  let timerId = null;

  function debounced(...args) {
    const callNow = immediate && timerId === null;

    clearTimeout(timerId);
    timerId = setTimeout(() => {
      timerId = null;
      if (!immediate) fn.apply(this, args);
    }, wait);

    if (callNow) fn.apply(this, args);
  }

  debounced.cancel = () => {
    clearTimeout(timerId);
    timerId = null;
  };

  return debounced;
}

// 使用範例
const onSearch = debounce((keyword) => {
  console.log("搜尋：", keyword);
}, 500);

onSearch("a");
onSearch("ab");
onSearch("abc"); // 只有最後一次會在 500ms 後執行：搜尋：abc

// 立即執行版本
const onClick = debounce(() => console.log("按鈕被點擊"), 1000, true);
onClick(); // 立即輸出
onClick(); // 1 秒內的重複呼叫被忽略

// 取消待執行的呼叫
onSearch.cancel();
```

